import{_ as a,o as r,c as d,a2 as l}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"سماجی ڈھانچہ اور طبقاتی نقل و حرکت","description":"","frontmatter":{},"headers":[],"relativePath":"ur/36-社会结构与阶层流动.md","filePath":"ur/36-社会结构与阶层流动.md","lastUpdated":null}'),o={name:"ur/36-社会结构与阶层流动.md"};function e(i,t,n,h,s,u){return r(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="سماجی-ڈھانچہ-اور-طبقاتی-نقل-و-حرکت" tabindex="-1">سماجی ڈھانچہ اور طبقاتی نقل و حرکت <a class="header-anchor" href="#سماجی-ڈھانچہ-اور-طبقاتی-نقل-و-حرکت" aria-label="Permalink to &quot;سماجی ڈھانچہ اور طبقاتی نقل و حرکت&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>36</td></tr><tr><td>ماڈیول</td><td>تہذیب کی ٹائپولوجی اور سماجی نظام</td></tr><tr><td>کلیدی الفاظ</td><td>سماجی ڈھانچہ، طبقاتی نقل و حرکت، کھلا نظام، منصفانہ ترقی، جمود مخالف</td></tr></tbody></table><h2 id="اولًا-سماجی-ڈھانچے-کے-بنیادی-تصورات-اور-سمبیوٹک-تہذیب-کی-تلاش" tabindex="-1">اولًا. سماجی ڈھانچے کے بنیادی تصورات اور سمبیوٹک تہذیب کی تلاش <a class="header-anchor" href="#اولًا-سماجی-ڈھانچے-کے-بنیادی-تصورات-اور-سمبیوٹک-تہذیب-کی-تلاش" aria-label="Permalink to &quot;اولًا. سماجی ڈھانچے کے بنیادی تصورات اور سمبیوٹک تہذیب کی تلاش&quot;">​</a></h2><p>سماجی ڈھانچہ سے مراد کسی معاشرے میں مختلف گروہوں کے درمیان تنظیم کا طریقہ اور تعلقات کا نمونہ ہے، جس میں طبقات کی تقسیم، کرداروں کی تقسیم، اقتدار کی تقسیم، وسائل کی تقسیم وغیرہ متعدد جہتیں شامل ہیں۔ کسی بھی تہذیبی شکل میں، سماجی ڈھانچہ فرد کی ترقی کے مواقع، معاشرے کی چلنے والی کارکردگی اور تہذیب کی طویل مدتی استحکام کو گہرا طور پر متاثر کرتا ہے۔</p><p>لوٹیرا سادھا نظام کے دور میں، سماجی ڈھانچہ انتہائی جمود اور عدم مساوات کو ظاہر کرتا تھا: طاقتور اور کمزور کے درمیان عبور نہ ہونے والا خلا موجود تھا، پیدائش قسمت کا تعین کرتی تھی، اور نچلے درجے کے جانداروں کے پاس تقریباً کوئی اوپر کی طرف نقل و حرکت کا امکان نہیں تھا۔ اس جمود والے سماجی ڈھانچے نے نہ صرف لامتناہی مصائب کا باعث بنا، بلکہ سماجی توانائی کے ضیاع اور تہذیب کے رک جانے کا باعث بھی بنا — زیادہ تر افراد کی صلاحیت ضائع ہو گئی، اور چند مفاد پرست افراد نے اپنے مراعات کو برقرار رکھنے کے لیے، جدت اور ترقی کو دبانے سے بھی نہیں ہچکچائے۔</p><p>اینکر سمبیوٹک تہذیب کے قیام کے بعد، &quot;کھلا، روانہ، منصفانہ، توانائی سے بھرا ہوا&quot; سماجی ڈھانچہ کی تعمیر کو بنیادی اہداف میں سے ایک قرار دیا گیا۔ سمبیوٹک تہذیب پختہ یقین رکھتی ہے: ایک صحت مند سماجی ڈھانچے کو ہر فرد کو اپنی محنت کے ذریعے قسمت بدلنے کے قابل ہونا چاہیے، سماجی وسائل کو سب سے زیادہ قابل، سب سے زیادہ شراکت کرنے والے افراد کی طرف بہنا چاہیے، اور مختلف طبقات کے درمیان روانہ روانہ چینلز کو برقرار رکھنا چاہیے۔ صرف اسی طرح، تمام سمبیوٹک جانداروں کی سرگرمی اور تخلیقی صلاحیتوں کو مکمل طور پر بیدار کیا جا سکتا ہے، اور تمام نسلوں کے مشترکہ ترقی کے عظیم مقصد کو حاصل کیا جا سکتا ہے۔</p><p>سمبیوٹک تہذیب کے سماجی ڈھانچے کی بنیادی تلاش کو چار جملوں میں خلاصہ کیا جا سکتا ہے:</p><ol><li><strong>کھلا اور جامع</strong>: معاشرہ تمام افراد کے لیے کھلا ہے، اور نسل، پیدائش، جنس وغیرہ کی وجہ سے داخلے کی رکاوٹیں نہیں ڈالتا</li><li><strong>روانہ نقل و حرکت</strong>: مختلف طبقات کے درمیان روانہ روانہ چینلز برقرار رکھے جاتے ہیں، اور فرد محنت کے ذریعے اوپر کی طرف نقل و حرکت حاصل کر سکتا ہے</li><li><strong>انصاف اور عدل</strong>: وسائل کی تقسیم اور مواقع کی فراہمی انصاف کے اصولوں پر عمل کرتی ہے، اور ہر فرد کے برابر ترقی کے مواقع ہیں</li><li><strong>توانائی سے بھرا ہوا</strong>: سماجی ڈھانچہ فرد کی سرگرمی اور تخلیقی صلاحیتوں کو بیدار کر سکتا ہے، اور کافی ترقی کی توانائی برقرار رکھ سکتا ہے</li></ol><h2 id="ثانیًا-سمبیوٹک-تہذیب-کی-سماجی-طبقات-کی-تقسیم" tabindex="-1">ثانیًا. سمبیوٹک تہذیب کی سماجی طبقات کی تقسیم <a class="header-anchor" href="#ثانیًا-سمبیوٹک-تہذیب-کی-سماجی-طبقات-کی-تقسیم" aria-label="Permalink to &quot;ثانیًا. سمبیوٹک تہذیب کی سماجی طبقات کی تقسیم&quot;">​</a></h2><p>سمبیوٹک تہذیب کی سماجی طبقات کی تقسیم پیدائش، نسل، دولت کو معیار کے طور پر نہیں لیتی، بلکہ &quot;سمبیوٹک ڈگری&quot; اور &quot;سادھا کی سطح&quot; کو بنیادی حوالہ کے طور پر لیتی ہے، اور ایک متحرک، کھلا طبقاتی نظام تشکیل دیتی ہے:</p><table tabindex="0"><thead><tr><th>طبقہ</th><th>نام</th><th>تناسب</th><th>بنیادی خصوصیات</th><th>بنیادی ذمہ داریاں</th></tr></thead><tbody><tr><td>پہلی پرت</td><td>سمبیوٹک رہنما</td><td>تقریباً 1%</td><td>位面 انتہائی طاقتور، سمبیوٹک ڈگری S-سطح، تہذیب کے بنیادی رہنما</td><td>حکمت عملی فیصلہ سازی، قوانین کی دیکھ بھال، بین位面 انتظامیہ</td></tr><tr><td>دوسری پرت</td><td>سمبیوٹک ریڑھ کی ہڈی</td><td>تقریباً 5%</td><td>اعلیٰ درجے کے سادھک، سمبیوٹک ڈگری A-سطح، ہر شعبے کی ریڑھ کی ہڈی کی طاقت</td><td>ٹیکنالوجی تحقیق و ترقی، تنظیمی انتظامیہ، اہلیت کی تربیت</td></tr><tr><td>تیسری پرت</td><td>سمبیوٹک پیشہ ور</td><td>تقریباً 20%</td><td>درمیانی درجے کے سادھک، سمبیوٹک ڈگری B-سطح، ہر صنعت کے پیشہ ور اہلیت</td><td>پیشہ ورانہ خدمات، ٹیکنالوجی کا اطلاق، بنیادی سطح کی انتظامیہ</td></tr><tr><td>چوتھی پرت</td><td>سمبیوٹک عوام</td><td>تقریباً 60%</td><td>ابتدائی درجے کے سادھک، سمبیوٹک ڈگری C-سطح، تہذیب کی بنیادی طاقت</td><td>بنیادی سادھا، پیداواری خدمات، کمیونٹی شرکت</td></tr><tr><td>پانچویں پرت</td><td>سمبیوٹک نئے آنے والے</td><td>تقریباً 14%</td><td>ابھی داخل ہونے والے یا بہتری کے امیدوار، سمبیوٹک ڈگری D-سطح، مدد اور رہنمائی کی ضرورت ہے</td><td>سیکھنا-بڑھنا، رہنمائی قبول کرنا، بتدریج ضم ہونا</td></tr></tbody></table><p>خاص طور پر اس بات پر زور دینے کی ضرورت ہے کہ یہ طبقاتی تقسیم مستقل نہیں ہے، بلکہ متحرک اور روانہ ہے۔ ہر فرد اپنی محنت کے ذریعے سمبیوٹک ڈگری اور سادھا کی سطح کو بڑھا سکتا ہے، اور طبقے کی اوپر کی طرف حاصل کر سکتا ہے؛ اس کے برعکس، اگر فرد ترقی نہ کرے یا یہاں تک کہ سمبیوٹک اخلاقیات کی خلاف ورزی کرے، تو طبقے کی نیچے کی طرف بھی ہو سکتی ہے۔</p><p>اس کے علاوہ، طبقات کی تقسیم کا مطلب مراعات اور امتیاز نہیں ہے۔ ہر طبقے کے افراد برابر بنیادی حقوق اور انسانی عزت سے لطف اندوز ہوتے ہیں، اور طبقے کا فرق بنیادی طور پر ذمہ داریوں کی تقسیم اور وسائل کی تقسیم میں ظاہر ہوتا ہے، انسانی عزت کی بلندی-پستی میں نہیں۔</p><h2 id="ثالثًا-طبقاتی-نقل-و-حرکت-کے-طریقے-اور-چینلز" tabindex="-1">ثالثًا. طبقاتی نقل و حرکت کے طریقے اور چینلز <a class="header-anchor" href="#ثالثًا-طبقاتی-نقل-و-حرکت-کے-طریقے-اور-چینلز" aria-label="Permalink to &quot;ثالثًا. طبقاتی نقل و حرکت کے طریقے اور چینلز&quot;">​</a></h2><p>سمبیوٹک تہذیب نے کثیر چینل، کثیر سطحی طبقاتی نقل و حرکت کا نظام قائم کیا ہے، اور اس بات کو یقینی بنایا ہے کہ ہر فرد کے پاس اپنی محنت کے ذریعے اوپر کی طرف نقل و حرکت حاصل کرنے کا موقع ہے:</p><h3 id="_3-1-سادھا-ترقی-کا-چینل" tabindex="-1">3.1 سادھا ترقی کا چینل <a class="header-anchor" href="#_3-1-سادھا-ترقی-کا-چینل" aria-label="Permalink to &quot;3.1 سادھا ترقی کا چینل&quot;">​</a></h3><p>سادھا ترقی سب سے اہم طبقاتی نقل و حرکت کا چینل ہے۔ سمبیوٹک تہذیب نے تین سو بنیادی سادھا نظاموں کی کھول کے ذریعے، ہر فرد کے لیے واضح سادھا ترقی کا راستہ فراہم کیا ہے:</p><ul><li><strong>سطح کی ترقی</strong>: سادھک سادھا کے ذریعے سطح کو بڑھاتا ہے، ابتدائی سے درمیانی، اعلیٰ، انتہائی، اور ہر سطح کا داخلہ طبقے کی اوپر کی طرف لے جا سکتا ہے</li><li><strong>نظام کا داخلہ</strong>: سادھک کسی مخصوص سادھا نظام میں داخلہ بخش نتائج حاصل کرتا ہے، تو سمبیوٹک ڈگری میں اضافہ اور طبقے کی اوپر کی طرف حاصل کر سکتا ہے</li><li><strong>ٹیکنالوجی جدت</strong>: سادھک سادھا ٹیکنالوجی، انجینئرنگ ٹیکنالوجی وغیرہ میں جدت بخش نتائج حاصل کرتا ہے، تو اعزاز اور وسائل کا انعام حاصل کر سکتا ہے، اور طبقے کی اوپر کی طرف کو تیز کر سکتا ہے</li></ul><p>سادھا ترقی کے چینل کا بنیادی اصول &quot;ہر ایک کا راستہ ہے&quot; ہے — چاہے پیدائش کچھ بھی ہو، جب تک محنت سے سادھا کیا جائے، تب تک طبقے کی اوپر کی طرف حاصل کرنے کا موقع ہے۔</p><h3 id="_3-2-شراکت-ترقی-کا-چینل" tabindex="-1">3.2 شراکت ترقی کا چینل <a class="header-anchor" href="#_3-2-شراکت-ترقی-کا-چینل" aria-label="Permalink to &quot;3.2 شراکت ترقی کا چینل&quot;">​</a></h3><p>سادھا کی سطح کے علاوہ، سمبیوٹک تہذیب میں شراکت بھی طبقاتی نقل و حرکت کی ایک اہم بنیاد ہے:</p><ul><li><strong>عوامی خدمات کی شراکت</strong>: اینکر کی دیکھ بھال، اساتذہ کی رہنمائی، ہنگامی بچاؤ وغیرہ عوامی خدمات میں حصہ لے کر، شراکت کی قدر جمع کرنا</li><li><strong>ٹیکنالوجی تحقیق و ترقی کی شراکت</strong>: سادھا ٹیکنالوجی، انجینئرنگ ٹیکنالوجی وغیرہ کے شعبوں میں تحقیق و ترقی کی شراکت کرنا</li><li><strong>ثقافتی تشہیر کی شراکت</strong>: سمبیوٹک فلسفے کی تشہیر کرنا، ثقافتی تخلیقات تخلیق کرنا، تہذیبی تبادلے کو فروغ دینا</li><li><strong>انتظامیہ شرکت کی شراکت</strong>: سماجی انتظامیہ میں حصہ لینا، پالیسی مشورے دینا، نظام کی بہتری کو تیز کرنا</li></ul><p>شراکت ترقی کے چینل کا بنیادی اصول &quot;زیادہ محنت زیادہ حاصل&quot; ہے — سمبیوٹک تہذیب میں جتنی زیادہ شراکت، اتنا زیادہ بدلہ اور طبقے کی بہتری حاصل کی جا سکتی ہے۔</p><h3 id="_3-3-تعلیم-ترقی-کا-چینل" tabindex="-1">3.3 تعلیم ترقی کا چینل <a class="header-anchor" href="#_3-3-تعلیم-ترقی-کا-چینل" aria-label="Permalink to &quot;3.3 تعلیم ترقی کا چینل&quot;">​</a></h3><p>تعلیم طبقاتی نقل و حرکت کی ایک اہم سیڑھی ہے۔ سمبیوٹک تہذیب نے مکمل تعلیم ترقی کا نظام قائم کیا ہے:</p><ul><li><strong>بنیادی تعلیم</strong>: ہر فرد کے لیے مفت بنیادی سادھا تعلیم فراہم کرنا، اور آغاز کے نقطے کے انصاف کو یقینی بنانا</li><li><strong>اعلیٰ تعلیم</strong>: امتحان کے ذریعے بہترین طلباء کو اعلیٰ سادھا کالج میں داخلے کے لیے منتخب کرنا، اور اعلیٰ سطح کی تربیت حاصل کرنا</li><li><strong>اشرافیہ تعلیم</strong>: سب سے زیادہ صلاحیت رکھنے والے افراد کو اشرافیہ تربیت کے منصوبے میں داخلے کے لیے منتخب کرنا، اور اعلیٰ ترین وسائل کی مدد حاصل کرنا</li><li><strong>زندگی بھر کی تعلیم</strong>: ہر عمر کے افراد کے لیے مسلسل سیکھنے اور بہتری کے مواقع فراہم کرنا</li></ul><p>تعلیم ترقی کے چینل کا بنیادی اصول &quot;مواقع کی مساوات&quot; ہے — ہر فرد کے پاس تعلیم کے ذریعے طبقے کی اوپر کی طرف حاصل کرنے کے برابر مواقع ہیں۔</p><h3 id="_3-4-خصوصی-ترقی-کا-چینل" tabindex="-1">3.4 خصوصی ترقی کا چینل <a class="header-anchor" href="#_3-4-خصوصی-ترقی-کا-چینل" aria-label="Permalink to &quot;3.4 خصوصی ترقی کا چینل&quot;">​</a></h3><p>خاص شعبوں میں خاص شراکت کرنے والے یا خاص صلاحیت ظاہر کرنے والے افراد کے لیے، سمبیوٹک تہذیب میں خصوصی ترقی کے چینلز موجود ہیں:</p><ul><li><strong>خاص اہلیت غیر معمولی ترقی</strong>: جو فرد کسی مخصوص شعبے میں خاص صلاحیت رکھتا ہے یا خاص شراکت کرتا ہے، وہ غیر معمولی طور پر طبقے کی بہتری حاصل کر سکتا ہے</li><li><strong>ہنگامی واقعات میں بہادری کی ترقی</strong>: ہنگامی واقعات (جیسے آفات، حملے، بحران وغیرہ) سے نمٹنے میں بہادری کرنے والے فرد تیز رفتار ترقی حاصل کر سکتا ہے</li><li><strong>بین位面 دریافت کی شراکت کی ترقی</strong>: بین位面 دریافت اور آثار قدیمہ میں خاص شراکت کرنے والے فرد ترقی حاصل کر سکتا ہے</li></ul><h2 id="رابعًا-طبقاتی-جمود-کو-روکنے-کے-نظام-کی-ضمانت" tabindex="-1">رابعًا. طبقاتی جمود کو روکنے کے نظام کی ضمانت <a class="header-anchor" href="#رابعًا-طبقاتی-جمود-کو-روکنے-کے-نظام-کی-ضمانت" aria-label="Permalink to &quot;رابعًا. طبقاتی جمود کو روکنے کے نظام کی ضمانت&quot;">​</a></h2><p>طبقاتی نقل و حرکت کی روانگی کے لیے نظام کی ضمانت درکار ہے۔ سمبیوٹک تہذیب نے طبقاتی جمود کو روکنے کے لیے درج ذیل نظام قائم کیے ہیں:</p><h3 id="_4-1-اجارہ-داری-مخالف-نظام" tabindex="-1">4.1 اجارہ داری مخالف نظام <a class="header-anchor" href="#_4-1-اجارہ-داری-مخالف-نظام" aria-label="Permalink to &quot;4.1 اجارہ داری مخالف نظام&quot;">​</a></h3><p>سمبیوٹک آئین اور اجارہ داری مخالف قانون واضح طور پر کسی بھی تنظیم یا فرد کو سادھا وسائل، سادھا نظام، تعلیمی مواقع وغیرہ پر اجارہ داری کرنے سے منع کرتا ہے۔ اجارہ داری مخالف نظام مفاد پرست گروہ کو وسائل پر اجارہ داری کرکے اپنے مراعات کو جمود کرنے سے روکتا ہے، اور وسائل کی کھولمنی اور روانگی کو یقینی بناتا ہے۔</p><h3 id="_4-2-وراثت-ٹیکس-اور-تحفہ-ٹیکس-کا-نظام" tabindex="-1">4.2 وراثت ٹیکس اور تحفہ ٹیکس کا نظام <a class="header-anchor" href="#_4-2-وراثت-ٹیکس-اور-تحفہ-ٹیکس-کا-نظام" aria-label="Permalink to &quot;4.2 وراثت ٹیکس اور تحفہ ٹیکس کا نظام&quot;">​</a></h3><p>دولت اور وسائل کی نسل در نسل منتقلی کے ذریعے طبقاتی جمود کو روکنے کے لیے، سمبیوٹک تہذیب میں بڑھتے ہوئے وراثت ٹیکس اور تحفہ ٹیکس کا نظام نافذ کیا جاتا ہے۔ اعلیٰ خالص قیمت والی وراثت اور تحفہ پر زیادہ تناسب کا ٹیکس ادا کرنا ہوتا ہے، جو عوامی وسائل کے تالاب میں شامل ہوتا ہے، اور تمام سمبیوٹک جانداروں کے مشترکہ مفاد کے لیے استعمال ہوتا ہے۔</p><h3 id="_4-3-تعلیمی-انصاف-کا-نظام" tabindex="-1">4.3 تعلیمی انصاف کا نظام <a class="header-anchor" href="#_4-3-تعلیمی-انصاف-کا-نظام" aria-label="Permalink to &quot;4.3 تعلیمی انصاف کا نظام&quot;">​</a></h3><p>سمبیوٹک تہذیب تعلیمی تحفظ کے قانون کے ذریعے تعلیمی انصاف کو یقینی بناتی ہے:</p><ul><li>بنیادی تعلیم تمام شہریوں کے لیے مفت کھلی ہے</li><li>اعلیٰ تعلیم اور اشرافیہ تعلیم کے انتخاب میں قابلیت اور صلاحیت کو معیار کے طور پر لیا جاتا ہے، پیدائش اور دولت کو نہیں</li><li>کمزور گروہوں کے لیے اضافی تعلیمی مدد اور معاوضہ فراہم کیا جاتا ہے</li><li>کسی بھی قسم کی تعلیمی امتیازی سلوک اور تعلیمی مراعات سے منع کیا جاتا ہے</li></ul><h3 id="_4-4-طبقاتی-نقل-و-حرکت-کی-نگرانی-کا-نظام" tabindex="-1">4.4 طبقاتی نقل و حرکت کی نگرانی کا نظام <a class="header-anchor" href="#_4-4-طبقاتی-نقل-و-حرکت-کی-نگرانی-کا-نظام" aria-label="Permalink to &quot;4.4 طبقاتی نقل و حرکت کی نگرانی کا نظام&quot;">​</a></h3><p>سمبیوٹک نیٹ ورک کا انفارمیشن کور وقتاً فوقتاً سماجی طبقات کی نقل و حرکت کی صورت حال کی نگرانی کرتا ہے، اور بنیادی نگرانی کے اشاریے درج ذیل ہیں:</p><ul><li><strong>نسل در نسل نقل و حرکت کی شرح</strong>: اولاد کے طبقے اور والدین کے طبقے کے فرق کی ڈگری</li><li><strong>اوپر کی طرف نقل و حرکت کی شرح</strong>: ہر چکر میں طبقے کی اوپر کی طرف حاصل کرنے والے افراد کا تناسب</li><li><strong>نیچے کی طرف نقل و حرکت کی شرح</strong>: ہر چکر میں طبقے کی نیچے کی طرف ہونے والے افراد کا تناسب</li><li><strong>طبقاتی جمود کا اشاریہ</strong>: ہر طبقے کے اندر &quot;وراثتی&quot; کی ڈگری</li></ul><p>جب نگرانی کے اشاریے یہ ظاہر کریں کہ طبقاتی نقل و حرکت میں رکاوٹ یا جمود کا رجحان ہے، تو انتظامی ادارے وقتاً فوقتاً پالیسی ایڈجسٹمنٹ کرتے ہیں، اور طبقاتی نقل و حرکت کی روانگی کو یقینی بناتے ہیں۔</p><h2 id="خامسًا-پانچ-تہذیبی-ٹائپولوجیوں-کے-سماجی-ڈھانچے-کے-فرق" tabindex="-1">خامسًا. پانچ تہذیبی ٹائپولوجیوں کے سماجی ڈھانچے کے فرق <a class="header-anchor" href="#خامسًا-پانچ-تہذیبی-ٹائپولوجیوں-کے-سماجی-ڈھانچے-کے-فرق" aria-label="Permalink to &quot;خامسًا. پانچ تہذیبی ٹائپولوجیوں کے سماجی ڈھانچے کے فرق&quot;">​</a></h2><p>پانچ سمبیوٹک تہذیبی ٹائپولوجیوں کے سماجی ڈھانچے میں ہر ایک کی اپنی خصوصیات ہیں:</p><table tabindex="0"><thead><tr><th>ٹائپولوجی</th><th>سماجی ڈھانچے کی خصوصیات</th><th>طبقاتی نقل و حرکت کی خصوصیات</th></tr></thead><tbody><tr><td>مشرقی ایشیا گھنے</td><td>اجتماعی رجحان، واضح درجہ بندی، خاندانی مذہبی ادارے پر مبنی</td><td>نقل و حرکت کے چینلز بنیادی طور پر مذہبی ادارے کی ترقی، نقل و حرکت کی رفتار درمیانی</td></tr><tr><td>شمالی یورپی فلاح و بہبود</td><td>چپٹا، اعلیٰ مساوات، کمزور طبقے</td><td>طبقے کا فرق کم، نقل و حرکت کا دباؤ کم، نقل و حرکت کی رفتار سست</td></tr><tr><td>شمالی امریکی کثیر الجہتی</td><td>بازار پر مبنی، کثیر الجہتی، شدید مقابلہ</td><td>نقل و حرکت کے چینلز بنیادی طور پر بازار مقابلہ، نقل و حرکت کی رفتار تیز لیکن فرق بڑا</td></tr><tr><td>یورپی براعظمی سماجی</td><td>کارپوریٹ ازم، مزدور-سرمایہ مشترکہ فیصلہ سازی، مشاورتی جمہوریت</td><td>نقل و حرکت کے چینلز بنیادی طور پر پیشہ ورانہ قابلیت اور اجتماعی گفتگو، نقل و حرکت مستحکم</td></tr><tr><td>ترقی پزیر پیچھے سے آگے نکلنے والی</td><td>مضبوط حکومت، تیز رفتار بہاؤ، تدریجی ترقی</td><td>نقل و حرکت کی رفتار تیز، اوپر جانے کے مواقع زیادہ، سماجی توانائی کافی</td></tr></tbody></table><p>اگرچہ ہر ٹائپولوجی کے سماجی ڈھانچے میں فرق موجود ہے، لیکن سب سمبیوٹک آئین کے بنیادی اصولوں پر عمل کرتے ہیں، اور سب کھلا، روانہ، منصفانہ، توانائی سے بھرا ہوا سماجی ڈھانچہ بنانے کے لیے پرعزم ہیں۔</p><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>سماجی ڈھانچہ اور طبقاتی نقل و حرکت اینکر سمبیوٹک تہذیب کے نظام کی تعمیر کے بنیادی موضوعات میں سے ایک ہے۔ سمبیوٹک تہذیب نے سمبیوٹک ڈگری اور سادھا کی سطح کو مرکز بنا کر متحرک طبقاتی تقسیم، کثیر چینل طبقاتی نقل و حرکت کے طریقے، اور طبقاتی جمود کو روکنے کے نظام کی ضمانت کے ذریعے ایک کھلا، روانہ، منصفانہ، توانائی سے بھرا ہوا سماجی ڈھانچہ بنایا ہے۔ اس طرح کے سماجی ڈھانچے میں، ہر فرد اپنی محنت کے ذریعے قسمت بدل سکتا ہے، سماجی وسائل سب سے زیادہ قابل، سب سے زیادہ شراکت کرنے والے افراد کی طرف بہہ سکتے ہیں، اور پوری تہذیب کافی ترقی کی توانائی برقرار رکھتی ہے۔ یہی وہ اہم سماجی بنیاد ہے جس کی وجہ سے سمبیوٹک تہذیب تمام نسلوں کے مشترکہ ترقی کو حاصل کرنے کے قابل ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>26-个体与集体平衡原理 (فرد اور اجتماعی توازن کا اصول)</li><li>29-共生度评估体系 (سمبیوٹک ڈگری تشخیصی نظام)</li><li>30-五种共生文明分型总览 (پانچ قسم کی سمبیوٹک تہذیب کی ٹائپولوجی کا جامع جائزہ)</li></ul>',51)])])}const b=a(o,[["render",e]]);export{_ as __pageData,b as default};
